//! LiteLLM HTTP client for the in-CLI agent runtime (v0.1 Wednesday).
//!
//! LiteLLM exposes an OpenAI-compatible Chat Completions API at
//! `POST /v1/chat/completions`. The `model` field in the request
//! is the *alias* declared in the user's `.ais` source (e.g. `fast`)
//! — LiteLLM's `model_list` config (generated by `aislang-compose`
//! in week 5) translates that alias to a concrete provider/model
//! pair, applies fallbacks per `router_settings.fallbacks`, and
//! handles auth from env vars (`os.environ/ANTHROPIC_API_KEY` etc.).
//!
//! v0.1 is non-streaming (Decision 3): one full response per turn.
//! v0.1 also doesn't pass `tools` (Thursday wires that). The
//! `LiteLlmClient` API is intentionally small — Wednesday gets the
//! `send_chat` round-trip working; Thursday adds `send_chat_with_tools`
//! as a new method on the same struct.

use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::time::Duration;
use thiserror::Error;

// week-9 Tue: OTel-GenAI semantic-convention instrumentation of
// `send_chat_full`. Spans are children of whatever `Context::current()`
// resolves to at call time — the CLI attaches the per-command root
// context (week 9 Mon) before invoking `chat_interactive` /
// `run_eval_inner`, so each LiteLLM call appears as a child of the
// root span in the trace tree.
use opentelemetry::{
    global,
    propagation::Injector,
    trace::{Span, SpanKind, TraceContextExt, Tracer},
    Array, Context, KeyValue, StringValue, Value,
};
use std::collections::HashMap;

// ============================================================================
// Wire types — OpenAI-compatible Chat Completions API
// ============================================================================

/// Top-level chat-completion request body.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ChatRequest {
    /// Model alias from the `.ais` `model` block (e.g. `"fast"`).
    /// LiteLLM resolves this through its `model_list` config.
    pub model:    String,
    pub messages: Vec<ChatMessage>,
    /// Non-streaming for v0.1 (Decision 3). Always `false` here; the
    /// field is sent explicitly to be unambiguous about it (some
    /// proxies default to streaming).
    pub stream:   bool,
    /// Tool catalog (week-6 Thu). When `None`, LiteLLM gets a plain
    /// chat request — same wire shape as Wed. When `Some(non-empty)`,
    /// the model is told what tools it can call; on its turn it can
    /// emit `tool_calls` on the assistant message.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tools:    Option<Vec<Tool>>,
    /// Per-request timeout hint surfaced to LiteLLM. Optional in the
    /// wire format — only set when the user pins it via the .ais
    /// `model.latency_p95` (v0.2).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub timeout:  Option<u64>,
    /// Upper bound on generated tokens. Optional — when `None`, the
    /// provider's default applies. v0.1 leaves this `None` everywhere
    /// (no `.ais` source field wires it through yet); the field
    /// exists so week-9 Tue can emit `gen_ai.request.max_tokens` on
    /// the OTel-GenAI span when v0.2 plumbs it.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub max_tokens: Option<u32>,
}

/// One message in a chat exchange.
///
/// `content` and `tool_calls` and `tool_call_id` are all optional —
/// which combination is valid depends on the `role`:
///   - **system**, **user**: require `content` (string).
///   - **assistant**: requires `content` OR `tool_calls` (or both).
///     When the model wants to invoke tools, it emits `tool_calls`
///     with no `content`; when it's giving a final answer, it emits
///     `content` with no `tool_calls`.
///   - **tool**: requires `content` (the tool's textual output) AND
///     `tool_call_id` (matching the assistant's `tool_calls[i].id`
///     so LiteLLM can pair them).
///
/// v0.1's chat loop manages the invariants. The struct itself is
/// permissive — invalid combinations are rejected by LiteLLM, not
/// here.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ChatMessage {
    pub role: Role,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub content: Option<String>,
    /// Tool invocations emitted by the assistant when it wants the
    /// runtime to dispatch one or more MCP calls. Populated on
    /// assistant messages only.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_calls: Option<Vec<ToolCall>>,
    /// Pairing key on `role=tool` messages — must match a
    /// `tool_calls[i].id` from the preceding assistant message.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_call_id: Option<String>,
}

impl ChatMessage {
    /// Helper: build a plain `{role, content}` message (system/user/
    /// tool-without-id). Most v0.1 call sites use this shape.
    pub fn text(role: Role, content: impl Into<String>) -> Self {
        Self {
            role,
            content: Some(content.into()),
            tool_calls: None,
            tool_call_id: None,
        }
    }

    /// Helper: build a tool-response message that pairs with a
    /// specific assistant `tool_calls[i].id`.
    pub fn tool_response(call_id: impl Into<String>, content: impl Into<String>) -> Self {
        Self {
            role: Role::Tool,
            content: Some(content.into()),
            tool_calls: None,
            tool_call_id: Some(call_id.into()),
        }
    }
}

// -- Tool wire types (OpenAI-compatible) ---------------------------------- //

/// One tool exposed to the model in the request's `tools` array.
/// `type` is always `"function"` for v0.1 (OpenAI also has
/// `code_interpreter` / `file_search` etc., but those don't apply
/// to MCP-routed tools).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Tool {
    #[serde(rename = "type")]
    pub kind: String,
    pub function: ToolFunction,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ToolFunction {
    pub name: String,
    pub description: String,
    /// JSON Schema describing the tool's input. Passed verbatim from
    /// the MCP server's `tools/list` response.
    pub parameters: serde_json::Value,
}

/// One tool invocation in an assistant message's `tool_calls` array.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ToolCall {
    /// Server-generated ID used to pair this call with its
    /// `role=tool` response message.
    pub id: String,
    #[serde(rename = "type")]
    pub kind: String,
    pub function: FunctionCall,
}

/// Quirk of the OpenAI spec: `function.arguments` is a JSON-encoded
/// **string** containing a JSON object, NOT a JSON object directly.
/// Callers must `serde_json::from_str(&call.function.arguments)` to
/// get the parsed argument map. Documented here so callers don't
/// have to re-discover it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FunctionCall {
    pub name: String,
    pub arguments: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Role {
    System,
    User,
    Assistant,
    /// Tool-response messages (used by the tool-use loop on Thursday).
    /// Carried through the v0.1 Wed type now so the wire format
    /// is forward-compatible.
    Tool,
}

/// What LiteLLM returns for a non-streaming chat completion. Mirrors
/// the OpenAI schema, with optional fields skipped — we only care
/// about `choices[0].message.content` for v0.1 Wed.  `Serialize` was
/// added v0.3 Week 18 Mon so the response body can be stamped as a
/// span attribute (debug visibility into "what did the LLM say?").
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ChatResponse {
    #[serde(default)] pub id:      Option<String>,
    #[serde(default)] pub model:   Option<String>,
    pub choices:                   Vec<ChatChoice>,
    /// Token usage — populated by LiteLLM when the upstream provider
    /// returns it. The budget counter in week 7 will key on this.
    #[serde(default)] pub usage:   Option<UsageStats>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ChatChoice {
    #[serde(default)] pub index:         u32,
    pub message:                          ChatMessage,
    #[serde(default)] pub finish_reason:  Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct UsageStats {
    #[serde(default)] pub prompt_tokens:     u32,
    #[serde(default)] pub completion_tokens: u32,
    #[serde(default)] pub total_tokens:      u32,
}

// ============================================================================
// Errors
// ============================================================================

#[derive(Debug, Error)]
pub enum LiteLlmError {
    #[error("HTTP request to LiteLLM at `{url}` failed: {cause}")]
    Transport { url: String, cause: String },

    #[error("LiteLLM returned HTTP {status} from `{url}`: {body}")]
    BadStatus { url: String, status: u16, body: String },

    #[error("could not parse LiteLLM response from `{url}`: {cause}\n--- body ---\n{body}")]
    BadResponse { url: String, cause: String, body: String },

    #[error("LiteLLM returned no choices (chat response had empty choices[])")]
    EmptyChoices,
}

// ============================================================================
// OTel-GenAI attribute helpers (week 9 Tue, Decision 18)
//
// The pure functions below build the attribute lists that go on the
// `chat <model>` span emitted by `send_chat_full`. Kept separate so
// they're testable without standing up the OTel SDK; the span-wiring
// code just calls these and pushes the KVs.
//
// Spec: https://opentelemetry.io/docs/specs/semconv/gen-ai/
// Naming convention: `gen_ai.<facet>.<field>`, all snake_case, units
// in the field name when ambiguous (e.g. `*_tokens`).
// ============================================================================

/// OTel-GenAI attribute keys we set on the LiteLLM child span. String
/// literals (no `opentelemetry-semantic-conventions::trace::*`
/// constant uses) for two reasons: the gen_ai namespace is still
/// moving in the spec, and keeping these inline makes the wire
/// contract greppable from one place.
pub(crate) mod gen_ai {
    /// Pin our wire contract: the values we emit MUST stay matched
    /// to the OTel-GenAI spec. Change-detector tests in `mod tests`
    /// below assert each constant value verbatim.
    pub const KEY_SYSTEM:           &str = "gen_ai.system";
    pub const KEY_REQUEST_MODEL:    &str = "gen_ai.request.model";
    pub const KEY_REQUEST_MAX_TOK:  &str = "gen_ai.request.max_tokens";
    pub const KEY_USAGE_INPUT:      &str = "gen_ai.usage.input_tokens";
    pub const KEY_USAGE_OUTPUT:     &str = "gen_ai.usage.output_tokens";
    pub const KEY_FINISH_REASONS:   &str = "gen_ai.response.finish_reasons";

    /// `gen_ai.system` value identifies the upstream provider as a
    /// short string. We send "litellm" because our HTTP wire endpoint
    /// IS LiteLLM — the concrete provider behind it (anthropic, openai,
    /// ollama …) is what LiteLLM resolves via its routing config.
    pub const SYSTEM_VALUE: &str = "litellm";
}

/// OTel-GenAI convention for span names: `<operation> <model>` (e.g.
/// `chat fast`). The operation for our wire is `chat` (chat-completion).
pub(crate) fn gen_ai_span_name(model_alias: &str) -> String {
    format!("chat {model_alias}")
}

/// Attributes known before the HTTP call — system identifier, request
/// model alias, and `max_tokens` (omitted when not set, per OTel
/// convention that optional fields are skipped rather than zeroed).
pub(crate) fn gen_ai_request_attrs(req: &ChatRequest) -> Vec<KeyValue> {
    let mut attrs = Vec::with_capacity(3);
    attrs.push(KeyValue::new(gen_ai::KEY_SYSTEM,
        gen_ai::SYSTEM_VALUE.to_string()));
    attrs.push(KeyValue::new(gen_ai::KEY_REQUEST_MODEL,
        req.model.clone()));
    if let Some(mt) = req.max_tokens {
        // i64 because OTel `Value::I64` is the only integer variant;
        // u32 fits losslessly.
        attrs.push(KeyValue::new(gen_ai::KEY_REQUEST_MAX_TOK, mt as i64));
    }
    attrs
}

/// Attributes derived from the response — token usage and finish
/// reasons. Both are conditional: some providers (Ollama in
/// particular) don't populate usage; degenerate responses may have
/// zero choices or choices without a finish_reason.
pub(crate) fn gen_ai_response_attrs(resp: &ChatResponse) -> Vec<KeyValue> {
    let mut attrs = Vec::with_capacity(3);
    if let Some(u) = &resp.usage {
        attrs.push(KeyValue::new(gen_ai::KEY_USAGE_INPUT,  u.prompt_tokens as i64));
        attrs.push(KeyValue::new(gen_ai::KEY_USAGE_OUTPUT, u.completion_tokens as i64));
    }
    let reasons: Vec<StringValue> = resp.choices.iter()
        .filter_map(|c| c.finish_reason.clone())
        .map(StringValue::from)
        .collect();
    if !reasons.is_empty() {
        attrs.push(KeyValue::new(
            gen_ai::KEY_FINISH_REASONS,
            Value::Array(Array::String(reasons)),
        ));
    }
    attrs
}

// ============================================================================
// `LiteLlmClient`
// ============================================================================

/// Thin HTTP client for LiteLLM's Chat Completions endpoint.
///
/// Pin the timeout at construction (v0.1 = 30s). One client instance
/// per chat session is fine — reqwest re-uses connections internally.
pub struct LiteLlmClient {
    http:     Client,
    base_url: String,
}

impl LiteLlmClient {
    /// Default LiteLLM port exposed by the compose stack (matches
    /// `litellm` service port mapping in `aislang-compose`).
    /// Default LiteLLM URL. Uses **`127.0.0.1`** explicitly (not
    /// `localhost`) to dodge a real-world bite: on Linux hosts where
    /// `/etc/hosts` maps `localhost` to both `127.0.0.1` and `::1`,
    /// reqwest's name resolution may try IPv6 first and hit Docker's
    /// flaky `[::]:4000->4000/tcp` mapping (it's listed but TCP
    /// connect frequently RSTs depending on kernel/userspace-proxy
    /// config). `127.0.0.1` is unambiguous IPv4 → straight to the
    /// `0.0.0.0:4000` published port → works everywhere.
    ///
    /// Observed week-7 Thu: with `localhost`, `curl http://localhost:4000/health/liveness`
    /// works (curl tries v4 after v6 fails) but reqwest's request
    /// surfaces "error sending request for url" because it commits
    /// to the first-resolved address. Pinning v4 sidesteps it.
    pub const DEFAULT_URL: &'static str = "http://127.0.0.1:4000";

    /// Env var overriding the LiteLLM base URL the agent dials.  Unset →
    /// [`Self::DEFAULT_URL`] (localhost — the local CLI / compose case).
    /// The K8s emitter sets this to the in-cluster service
    /// `http://litellm:4000` on the agent-runtime pod, since there LiteLLM
    /// is a sibling pod, NOT localhost.
    pub const URL_ENV_VAR: &'static str = "AISLANG_LITELLM_URL";

    /// The LiteLLM base URL from [`Self::URL_ENV_VAR`], if set + non-empty.
    /// Callers pass the result as the `litellm_url` arg to `Session::open*`
    /// (None → the session uses [`Self::DEFAULT_URL`]).
    pub fn url_from_env() -> Option<String> {
        std::env::var(Self::URL_ENV_VAR).ok()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
    }

    /// 300 seconds (5 minutes). Sized for CPU-bound local inference
    /// (Ollama on a developer laptop generating a 4k-token response
    /// can comfortably take 60-180s; eval datasets exercise the
    /// long tail of those generations).
    ///
    /// History: 30s (v0.1) → 180s (v0.1 week 8, long-form answers
    /// against Llama 3.1 8B on CPU) → 300s (v0.3 week 20 Mon, user
    /// report against qwen3:8b on CPU which can comfortably exceed
    /// 3 min for the Architect's reasoning-heavy 5-section markdown
    /// designs).  5 min is generous for local models AND still
    /// bounds a wedged proxy from blocking the chat loop
    /// indefinitely.  Fast cloud models (Haiku, gpt-4o-mini, Sonnet)
    /// complete well under 30s, so the longer ceiling doesn't hurt
    /// their UX.
    ///
    /// Override at runtime via the `AISLANG_LITELLM_TIMEOUT_SECS`
    /// env var (clamped to 1..=3600 to bound the worst case).
    /// `Self::new` reads the env var on each construction.
    ///
    /// v0.5+: make this configurable per-eval / per-session via the
    /// `.ais` source's `model.latency_p95` field (currently used
    /// only as a resolver constraint), with a fallback to this
    /// constant.  Catalog entry's `latency_p95 * 4` is a reasonable
    /// per-call timeout derivation but underestimates for CPU-bound
    /// hardware where the catalog's GPU-tuned latency_p95 values are
    /// off by an order of magnitude.
    pub const DEFAULT_TIMEOUT_SECS: u64 = 300;

    /// Env var read by `Self::new` to override
    /// [`DEFAULT_TIMEOUT_SECS`](Self::DEFAULT_TIMEOUT_SECS) at
    /// runtime.  Value parses as `u64` seconds, clamped to
    /// `1..=3600` to keep both extremes bounded.  Missing /
    /// malformed values fall through to the default.
    pub const TIMEOUT_ENV_VAR: &'static str = "AISLANG_LITELLM_TIMEOUT_SECS";

    /// Build a client pointing at the given LiteLLM base URL.
    /// `base_url` must NOT include the `/v1/...` path — that's
    /// appended per-call.
    ///
    /// Per-call timeout: `DEFAULT_TIMEOUT_SECS` unless the
    /// `AISLANG_LITELLM_TIMEOUT_SECS` env var supplies a parseable
    /// override (clamped to 1..=3600).
    pub fn new(base_url: impl Into<String>) -> Result<Self, LiteLlmError> {
        let base_url = base_url.into();
        let timeout_secs = resolve_timeout_secs();
        let http = Client::builder()
            .timeout(Duration::from_secs(timeout_secs))
            .build()
            .map_err(|e| LiteLlmError::Transport {
                url:   base_url.clone(),
                cause: e.to_string(),
            })?;
        Ok(Self { http, base_url })
    }

    /// `Self::new(DEFAULT_URL)`. Convenience for the most common case.
    pub fn default_local() -> Result<Self, LiteLlmError> {
        Self::new(Self::DEFAULT_URL)
    }

    /// POST a non-streaming chat completion. Returns the first
    /// choice's assistant message content as a plain `String`.
    ///
    /// For requests with no `tools` array (Wed-style simple turns),
    /// this is the most ergonomic API. For tool-use turns the loop
    /// needs access to `tool_calls`; use [`send_chat_full`] instead.
    pub async fn send_chat(&self, req: &ChatRequest) -> Result<String, LiteLlmError> {
        let response = self.send_chat_full(req).await?;
        let first = response.choices.into_iter().next()
            .ok_or(LiteLlmError::EmptyChoices)?;
        Ok(first.message.content.unwrap_or_default())
    }

    /// POST a non-streaming chat completion and return the full
    /// parsed `ChatResponse`. Required by the tool-use loop (Thu)
    /// because it needs `choices[0].message.tool_calls`, not just
    /// the textual content.
    ///
    /// **OTel-GenAI instrumentation** (week 9 Tue, Decision 18):
    /// each call opens a `chat <model>` Client-kind span as a child
    /// of `Context::current()` (the per-command root attached by the
    /// CLI's sync wrapper). Pre-call attributes are set from `req`;
    /// post-call attributes (`gen_ai.usage.*`, `gen_ai.response.finish_reasons`)
    /// are set from the parsed `ChatResponse`. Latency = span
    /// duration, computed automatically by the SDK.
    pub async fn send_chat_full(&self, req: &ChatRequest) -> Result<ChatResponse, LiteLlmError> {
        let url = format!("{}/v1/chat/completions", self.base_url);

        // Open the span BEFORE the HTTP call so its duration captures
        // request serialization + network round-trip + body parsing.
        let tracer = global::tracer("aislang");
        let mut span = tracer.span_builder(gen_ai_span_name(&req.model))
            .with_kind(SpanKind::Client)
            .with_attributes(gen_ai_request_attrs(req))
            .start(&tracer);
        // v0.3 Week 18 Mon follow-up: stamp the request body as a
        // span attr so Jaeger shows the actual prompt the model
        // saw.  Truncation cap 8 KB — chat requests with bundled
        // system prompt + RAG context can run long; this fits the
        // typical case while staying clickable in the UI.  Uses
        // the same truncate helper as session.rs's span attrs.
        if let Ok(req_json) = serde_json::to_string(req) {
            span.set_attribute(KeyValue::new(
                "aislang.chat.request_json",
                crate::session::truncate_for_span_attr(&req_json, 8192)));
            span.set_attribute(KeyValue::new(
                "aislang.chat.request_bytes_total", req_json.len() as i64));
        }

        // v0.3 Week 18 Mon follow-up: inject W3C trace context into
        // the outbound LiteLLM request so LiteLLM's OTel callback
        // makes its spans CHILDREN of THIS `chat <model>` span.
        // Net effect in Jaeger: one trace per chat_turn covers both
        // aislang-mcp-serve AND litellm spans — directly correlated
        // by trace_id instead of needing to match `chatcmpl-*` ↔
        // `msg_*` IDs across service boundaries.
        //
        // We build a Context that explicitly contains OUR span
        // (rather than relying on Context::current()) because the
        // surrounding async function may not have our span attached
        // as the thread-local current — we just started it via
        // `span_builder.start()` without `Context::current_with_span`.
        let mut carrier = HashMap::<String, String>::new();
        let propagation_ctx = Context::current().with_remote_span_context(
            span.span_context().clone());
        global::get_text_map_propagator(|propagator| {
            propagator.inject_context(&propagation_ctx,
                &mut HeaderInjector(&mut carrier));
        });

        // Attach the propagation headers (typically `traceparent` +
        // optionally `tracestate`) before .json/.send.  reqwest's
        // RequestBuilder fluent chain just walks the carrier map.
        let mut request = self.http.post(&url).json(req);
        for (k, v) in &carrier {
            request = request.header(k, v);
        }
        let response = request.send().await
            .map_err(|e| {
                // Span ends on Drop with whatever attrs are set;
                // status defaults to "Unset" — that's fine for v0.1.
                // Tue/Wed don't need `span.set_status(Error)` yet;
                // Thu can add error semantics if useful for the
                // demo. (Decision 21: telemetry is observational —
                // never adds caller-visible behaviour.)
                let _ = &span; // explicit no-op to silence "moved" lints
                LiteLlmError::Transport {
                    url:   url.clone(),
                    cause: e.to_string(),
                }
            })?;
        let status = response.status();
        let body = response.text().await.unwrap_or_default();
        if !status.is_success() {
            return Err(LiteLlmError::BadStatus {
                url,
                status: status.as_u16(),
                body,
            });
        }
        let parsed: ChatResponse = serde_json::from_str(&body)
            .map_err(|e| LiteLlmError::BadResponse {
                url:   url.clone(),
                cause: e.to_string(),
                body:  body.clone(),
            })?;

        // Response-derived attrs go on the span before it ends.
        for kv in gen_ai_response_attrs(&parsed) {
            span.set_attribute(kv);
        }
        // v0.3 Week 18 Mon follow-up: stamp the response BODY too
        // (truncated).  Pairs with `aislang.chat.request_json` above
        // so each `chat <model>` span carries the full Q&A in one
        // place — exactly the visibility the user needed to debug
        // "why did the classifier pick X?" / "what did the model
        // actually say?".  We dump the full ChatResponse JSON so
        // tool_calls + finish_reason + usage are all greppable in
        // Jaeger without re-fetching.
        if let Ok(resp_json) = serde_json::to_string(&parsed) {
            span.set_attribute(KeyValue::new(
                "aislang.chat.response_json",
                crate::session::truncate_for_span_attr(&resp_json, 8192)));
            span.set_attribute(KeyValue::new(
                "aislang.chat.response_bytes_total", resp_json.len() as i64));
        }
        span.end();
        Ok(parsed)
    }
}

// ============================================================================
// Helper: resolve the per-call timeout — env-var override + clamp.
// ============================================================================

/// Read `AISLANG_LITELLM_TIMEOUT_SECS` and clamp into `1..=3600`,
/// falling through to [`LiteLlmClient::DEFAULT_TIMEOUT_SECS`] on
/// missing / unparseable values.  Used by `LiteLlmClient::new` on
/// every construction so override-then-rebuild works without a
/// process restart.
fn resolve_timeout_secs() -> u64 {
    const MIN: u64 = 1;
    const MAX: u64 = 3600;
    match std::env::var(LiteLlmClient::TIMEOUT_ENV_VAR) {
        Ok(s) => match s.parse::<u64>() {
            Ok(v) => v.clamp(MIN, MAX),
            Err(_) => LiteLlmClient::DEFAULT_TIMEOUT_SECS,
        },
        Err(_) => LiteLlmClient::DEFAULT_TIMEOUT_SECS,
    }
}

#[cfg(test)]
mod timeout_tests {
    use super::*;

    // The env var is process-global so each case sets+clears to
    // keep the next case's setup deterministic.  Using a single
    // test fn with serial calls (NOT separate #[test] fns) so
    // cargo's parallel test runner can't interleave them.
    #[test]
    fn resolve_timeout_secs_env_var_round_trip_and_clamp() {
        let v = LiteLlmClient::TIMEOUT_ENV_VAR;

        // ── unset → default ─────────────────────────────────
        // SAFETY: setting/removing env vars in tests is unsafe
        // in edition 2024+ because another thread could be
        // reading the env concurrently.  These tests are
        // single-threaded by design (#[test] alone, no async
        // dispatch), so the only reader is this test itself.
        unsafe { std::env::remove_var(v); }
        assert_eq!(resolve_timeout_secs(), LiteLlmClient::DEFAULT_TIMEOUT_SECS);

        // ── valid value passes through ──────────────────────
        unsafe { std::env::set_var(v, "600"); }
        assert_eq!(resolve_timeout_secs(), 600);

        // ── below MIN clamps up to 1 ────────────────────────
        unsafe { std::env::set_var(v, "0"); }
        assert_eq!(resolve_timeout_secs(), 1);

        // ── above MAX clamps down to 3600 ───────────────────
        unsafe { std::env::set_var(v, "99999"); }
        assert_eq!(resolve_timeout_secs(), 3600);

        // ── unparseable falls back to default ───────────────
        unsafe { std::env::set_var(v, "five-hundred"); }
        assert_eq!(resolve_timeout_secs(), LiteLlmClient::DEFAULT_TIMEOUT_SECS);

        // Clean up.
        unsafe { std::env::remove_var(v); }
    }
}

// ============================================================================
// Helper: build a one-turn ChatRequest (system + user) — used by both
// the session module and tests that pin the wire shape.
// ============================================================================

/// Build a request with one system message + one user message + no
/// tools. Stream is hard-set to `false` per Decision 3. Used by
/// callers that aren't running a tool-use loop (e.g. the prompt
/// hashing harness, tests).
pub fn one_turn_request(model: &str, system: &str, user: &str) -> ChatRequest {
    ChatRequest {
        model:      model.to_string(),
        messages: vec![
            ChatMessage::text(Role::System, system),
            ChatMessage::text(Role::User,   user),
        ],
        stream:     false,
        tools:      None,
        timeout:    None,
        max_tokens: None,
    }
}

// ============================================================================
// W3C trace-context propagation — outbound HTTP header injection
// ============================================================================

/// Adapter that lets `opentelemetry`'s `TextMapPropagator` write into
/// a plain `HashMap<String, String>` (later copied into reqwest's
/// `RequestBuilder::header`).  We can't inject directly into
/// `reqwest::header::HeaderMap` because the trait bound conflicts
/// (HeaderMap requires `HeaderName`/`HeaderValue` types, not plain
/// strings), and we don't want to depend on the heavier
/// `opentelemetry-http` crate just for one adapter.
pub(crate) struct HeaderInjector<'a>(pub(crate) &'a mut HashMap<String, String>);

impl<'a> Injector for HeaderInjector<'a> {
    fn set(&mut self, key: &str, value: String) {
        self.0.insert(key.to_string(), value);
    }
}

